window.CONTROVERSIES = {"note": "Hand-verified ministerial controversies, May 2022 onward. Each entry: what happened (as reported), the minister's/government's response, and the outcome, with at least two reputable sources. Categories are descriptive labels, not findings by this site.", "categories": ["Taxpayer money & entitlements", "Conduct & remarks", "Integrity & conflicts of interest", "Misleading statements", "Decisions & judgement", "Appointments & process", "Other"], "items": [{"id": "albanese-takaichi-melons-podcast", "date": "2026-08-10", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM's 'melons' podcast remark about Japanese PM Takaichi's gift draws apology demands", "category": "Conduct & remarks", "summary": "On comedian Nikki Osborne's Bush Deep podcast (released early July 2026), Albanese recalled being gifted two crown melons by Japanese Prime Minister Sanae Takaichi during her May 2026 visit, describing the gift as 'pretty strange' but 'quite good'. Osborne joked 'She brought two. She just came in looking like Pamela Anderson'; Albanese replied 'She brought two, and they're beautiful' while gesturing with his hands, which critics read as mimicking a woman's chest. An AAP FactCheck (13 July) found the Pamela Anderson comparison was made by Osborne, not the PM. The issue escalated on 10 August when former Japanese ambassador Shingo Yamagami criticised the remarks in The Australian and Opposition Leader Angus Taylor demanded a personal apology to Takaichi. On 12 August an internal Japanese government memo, which said Japan saw no 'ill intention' and would not raise the matter, was leaked to Australian media; Liberal senator James Paterson referred the leak to the AFP.", "response": "The PM's office said the assertion that he mimicked Takaichi's body 'is incorrect'. In Parliament Albanese said 'I reject the assertion in the question' and that 'Prime Minister Takaichi is a friend of Australia and a friend of mine'. Japan's ambassador Kazuhiro Suzuki said Japan had been 'informed by the Australian side that Prime Minister Albanese did not make the comments in the way that has been reported'.", "outcome": "No apology to Takaichi; no formal finding. Japan did not formally raise the matter. AFP acknowledged a referral over the memo leak (not over the PM's conduct). Albanese separately conceded appearing on the podcast was 'an error'.", "status": "no-finding", "sources": [{"title": "Taylor demands Albanese apologise to Japan PM Sanae Takaichi over melon gesture", "url": "https://www.abc.net.au/news/2026-08-10/taylor-demands-albanese-apologise-to-takaichi/107017790", "date": "2026-08-10"}, {"title": "Japan responds to Albanese's 'melon' gesture, playing down concerns", "url": "https://www.abc.net.au/news/2026-08-12/melon-gesture-japanese-memo-afp-referral/106840234", "date": "2026-08-12"}, {"title": "Podcaster's quip about Japan PM's 'melons' misattributed to Albanese (AAP FactCheck)", "url": "https://www.aap.com.au/factcheck/podcasters-quip-about-japan-pms-melons-misattributed-to-albanese/", "date": "2026-07-13"}, {"title": "Albanese's office rejects claim he mimicked Japanese PM's breasts during podcast", "url": "https://www.sbs.com.au/news/article/anthony-albanese-melons-comment-japan-sanae-takaichi/dl1otgfth", "date": "2026-08-10"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "bowen-275-power-bill-promise-2026", "date": "2026-07-05", "minister": "Chris Bowen", "portfolio": "Minister for Climate Change and Energy", "title": "Bowen declines to address unmet $275 power-bill pledge as $22.7bn extra billing reported", "category": "Misleading statements", "summary": "Labor's 2022 election commitment, championed by Bowen, was to cut household power bills by $275 a year by 2025. In July 2026 Coalition analysis of energy regulator data put the additional amount paid by National Electricity Market consumers since 2022 at $22.7 billion. Bowen conceded bills were too high but did not address the $275 pledge, attributing prices to the international energy crisis and 'denial and delay' under the Coalition. At the 10 April 2025 National Press Club energy debate he had declined to give any dollar figure, saying only that 'energy prices will be cheaper under us than under Mr O'Brien'.", "response": "Bowen blamed the Ukraine-driven energy shock and the previous government's record, and said Labor was making 'very good progress on the renewables rollout'.", "outcome": "No formal finding; the pledge remains unmet and is regularly cited by the Opposition as a broken promise.", "status": "no-finding", "sources": [{"title": "Energy Minister Chris Bowen says huge energy bill blowout due to past 'denial and delay'", "url": "https://thenightly.com.au/politics/energy-minister-chris-bowen-says-huge-energy-bill-blowout-due-to-past-denial-and-delay-c-22533146", "date": "2026-07-05"}, {"title": "'Happy for Australia to go broke': Major parties face off over price of power bills", "url": "https://www.sbs.com.au/news/article/bowen-and-obrien-face-off-over-price-of-power-bills/5nvt5s6v0", "date": "2025-04-10"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "albanese-kylie-minogue-shag-marry-date", "date": "2026-07-03", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM apologises 'unequivocally' for 'shag, marry, date' answer about Kylie Minogue", "category": "Conduct & remarks", "summary": "In an episode of Nikki Osborne's Bush Deep podcast released on Friday 3 July 2026, Albanese was asked to play 'shag, marry, date' with Kylie Minogue, Nicole Kidman and Rhonda Burchmore. He initially declined, citing his recent marriage, but when pressed on a hypothetical said 'Oh, Kylie clearly' and, asked whether he would marry, shag and date her, replied 'All of the above'. He also made remarks about his own sex life. Community Strong MP Zali Steggall called his participation 'entirely inappropriate'; Liberal senator Sarah Henderson called it 'crude locker room talk'.", "response": "On Monday 6 July Albanese issued a statement: 'I apologise unequivocally for the comments.' He later said appearing on the podcast was 'an error'. Acting PM Richard Marles and Tanya Plibersek defended his record on gender equality.", "outcome": "Public apology; no formal finding. Minogue did not comment publicly.", "status": "resolved", "sources": [{"title": "Anthony Albanese 'unequivocally' apologises for saying he would 'shag' Kylie Minogue during podcast game", "url": "https://www.abc.net.au/news/2026-07-06/albanese-apologises-shag-kylie-minogue-podcast-comment/106883266", "date": "2026-07-06"}, {"title": "Australia's PM Apologizes for 'Inappropriate' Comment About Kylie Minogue", "url": "https://time.com/article/2026/07/06/anthony-albanese-australia-prime-minister-apologizes-shag-kylie-minogue-controversy/", "date": "2026-07-06"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "conroy-defence-procurement-hunter-frigates", "date": "2026-07-01", "minister": "Pat Conroy", "portfolio": "Minister for Defence Industry", "title": "Conroy grilled on $29bn in defence cost blowouts and $27bn Hunter frigate program", "category": "Decisions & judgement", "summary": "A government task force found $29 billion in cost overruns across defence procurement projects before contracts were even signed, with an average 38 per cent cost increase at pre-contract stage. On 7.30, Conroy said the system was 'broken' and that on the Hunter-class frigates '$500 million worth of changes were made to the design without talking to the people actually building the ship'. By September 2026 the ABC reported roughly $27 billion would be spent to deliver the first three Hunter frigates, with the program cut from nine ships to six and the first not due until 2032; analyst Marcus Hellyer questioned whether the design tried to do too much.", "response": "Conroy attributed the failures to structural problems rather than individuals, announced 'the biggest reforms to the defence organisation in 50 years' including a single national armaments director, and said he made 'no apologies' for the frigates' advanced radar.", "outcome": "Procurement reforms announced; program continues under scrutiny.", "status": "ongoing", "sources": [{"title": "Defence Industry Minister Pat Conroy defends defence spending", "url": "https://www.abc.net.au/news/2026-07-01/defence-industry-minister-pat-conroy-defends-defence-spending/106867174", "date": "2026-07-01"}, {"title": "Australia is spending $27 billion to build three warships. Will it be worth it?", "url": "https://www.abc.net.au/news/2026-09-14/federal-politics-australia-billions-spent-on-three-warships/107132330", "date": "2026-09-14"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "rae-aged-care-assessment-algorithm", "date": "2026-06-04", "minister": "Sam Rae", "portfolio": "Minister for Aged Care and Seniors", "title": "Rae defends aged-care funding algorithm that assessors cannot override", "category": "Decisions & judgement", "summary": "The Integrated Assessment Tool uses an algorithm to set Support at Home funding levels, and human assessors lost the ability to overrule its classification; officials admitted there was no consultation with providers or advocates before that change. Following hundreds of complaints, 132 people had to be reassessed by June 2026 and more than 1,000 review requests were lodged in five months. Rae was grilled on radio and in Parliament, and the Coalition, Greens, crossbench and some Labor backbenchers pushed legislation to restore human override, which the government resisted. Shadow minister Anne Ruston called Rae's rapid review 'a damning admission that the tool is failing'.", "response": "Rae said he was 'not satisfied with the prioritisation mechanism', ordered a three-month departmental review, and in July announced an escalation pathway for complex cases while ruling out reinstating human override. Health Minister Mark Butler said the tool delivered the 'predictability and consistency' the Royal Commission recommended.", "outcome": "Departmental review and limited escalation pathway; calls to scrap the algorithm continue.", "status": "ongoing", "sources": [{"title": "Aged Care Minister Sam Rae grilled over human involvement in aged care assessments", "url": "https://www.abc.net.au/news/2026-06-04/sam-rae-defends-aged-care-assessment-tool/106758892", "date": "2026-06-04"}, {"title": "'Damning admission': Labor concession on controversial aged care tool fails to quell anger", "url": "https://www.sbs.com.au/news/article/aged-care-integrated-assessment-tool-algorithm-labor-changes/sd68zwgnp", "date": "2026-07-02"}, {"title": "Labor resists widespread calls to ditch 'cruel' aged care funding algorithm", "url": "https://www.abc.net.au/news/2026-08-19/labor-stands-by-algorithm-aged-care-assessment-tool/107055252", "date": "2026-08-19"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "bowen-international-travel-cop31", "date": "2026-05-26", "minister": "Chris Bowen", "portfolio": "Minister for Climate Change and Energy", "title": "Bowen's overseas travel bill and COP31 department travel questioned by Opposition", "category": "Taxpayer money & entitlements", "summary": "Documents obtained by The Australian (reported by AAP, 26 May 2026) showed climate department staff were authorised to spend $485,602 on travel to Turkey, Fiji, Germany and Korea in January–February 2026 in preparation for Australia's COP31 role, with the overall COP31 role budgeted at more than $150 million. On 6 August 2026 News Corp outlets reported IPEA data showing Bowen and accompanying staff spent $345,000 over 46 days of international travel in 2025–26, including a $118,030 nine-day US visit, $79,233 to Brazil and Chile, $45,052 to Denmark, Finland and Singapore and $41,443 to Germany and Singapore. Opposition energy spokesman Dan Tehan said Bowen should explain how the spending had 'led to cheaper power bills'.", "response": "Bowen called Tehan 'the biggest hypocrite in the federal parliament', citing Tehan's own ministerial travel. Bowen's spokesperson said the minister 'regularly engages with counterparts ... via videoconference' and that 'international travel is used only when other communication means are deemed ineffective'.", "outcome": "No formal finding; travel reported through IPEA as within entitlements.", "status": "no-finding", "sources": [{"title": "'Biggest hypocrite': clash over climate expenses (AAP)", "url": "https://www.dailyliberal.com.au/story/9253827/biggest-hypocrite-clash-over-climate-expenses/", "date": "2026-05-26"}, {"title": "'Beggars belief' - Chris Bowen's monster travel bill continues to rise (2GB)", "url": "https://www.2gb.com/beggars-belief-chris-bowens-monster-travel-bill-continues-to-rise/", "date": "2026-05-22"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "keogh-invictus-australia-funding-cut", "date": "2026-05-13", "minister": "Matt Keogh", "portfolio": "Minister for Veterans' Affairs and Defence Personnel", "title": "Keogh reverses Budget decision to end $9m Invictus Australia funding after outcry", "category": "Decisions & judgement", "summary": "The 12 May 2026 Budget did not renew a $9 million, three-year funding commitment (about $3 million a year since 2022–23) to Invictus Australia, which runs sport-based recovery programs for veterans. Invictus Australia CEO Michael Hartung called it 'a devastating blow' and said Australia might not field a team for the 2027 Birmingham Games; athlete Vanessa Broughill told the ABC the cut 'can be life-threatening'.", "response": "Keogh initially said the grant program had concluded and the new Veteran and Family Wellbeing Agency would 'provide future opportunities to work with the sector to develop a competitive program'. On 28 May 2026 he announced on A Current Affair that funding would continue for a further three years.", "outcome": "Decision reversed on 28 May 2026; funding reinstated for three years. The reversal was later cited by the Opposition as one of several Keogh 'backflips'.", "status": "resolved", "sources": [{"title": "Veterans warn Invictus Australia budget cut could be life-threatening", "url": "https://www.abc.net.au/news/2026-05-13/veterans-warning-invictus-australia-budget-cut-life-threatening/106676148", "date": "2026-05-13"}, {"title": "Budget Win for Veteran & Family Wellbeing: Funding Reinstated to Invictus Australia", "url": "https://invictusaustralia.org/funding-reinstated-2026/", "date": "2026-05-28"}, {"title": "Matt Keogh under fire in Federal Parliament over 'cruel cuts' to veterans' services and botched meeting", "url": "https://thenightly.com.au/politics/australia/matt-keogh-under-fire-in-federal-parliament-over-cruel-cuts-to-veterans-services-and-botched-meeting-c-22752835", "date": "2026-08-20"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "keogh-veterans-allied-health-cap", "date": "2026-05-12", "minister": "Matt Keogh", "portfolio": "Minister for Veterans' Affairs and Defence Personnel", "title": "Keogh's $5,000 veterans' allied-health cap scrapped after four months of backlash", "category": "Decisions & judgement", "summary": "The May 2026 Budget (12 May) introduced a $5,000 annual threshold on DVA-funded allied health services (e.g. physiotherapy, dentistry) for veterans from 1 July 2027, replacing the existing 12-visit GP re-referral rule; the measure was linked to savings reported at roughly $700–779 million over four years. RSL Australia and ten national ex-service organisations issued a joint open letter opposing it, and the Senate passed an urgency motion (8 September) and reversal amendments (10 September). In Parliament on 18–20 August 2026, Keogh apologised for initially declining to meet a veterans' delegation (the Coalition of Veterans' Voices), whose members accused him of refusing to shake hands and rolling his eyes at the eventual meeting; the Coalition attempted to censure him.", "response": "On 17 September 2026 Keogh said: 'We have been consulting on this measure, and we have heard from veterans there are concerns about this approach,' and confirmed the threshold was 'off the table'. He had earlier told Parliament he 'got it wrong' by declining the meeting.", "outcome": "Policy withdrawn on 17 September 2026 before taking effect. Opposition Leader Angus Taylor said it had 'taken too long' and called for Keogh to resign; no resignation. A related $9 million Invictus Australia funding cut in the same Budget was also reversed (see separate entry).", "status": "resolved", "sources": [{"title": "Government bows to pressure to scrap allied health cap for veterans", "url": "https://www.abc.net.au/news/2026-09-17/veterans-allied-health-cap-backflip-government-keogh-lambie/107162722", "date": "2026-09-17"}, {"title": "Matt Keogh under fire in Federal Parliament over 'cruel cuts' to veterans' services and botched meeting", "url": "https://thenightly.com.au/politics/australia/matt-keogh-under-fire-in-federal-parliament-over-cruel-cuts-to-veterans-services-and-botched-meeting-c-22752835", "date": "2026-08-20"}, {"title": "Veteran Allied Health Care Cap — RSL Australia", "url": "https://www.rslaustralia.org/allied-health-cap", "date": "2026-09-17"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "king-inland-rail-consolidated-2026", "date": "2026-05-05", "minister": "Catherine King", "portfolio": "Minister for Infrastructure, Transport, Regional Development and Local Government", "title": "Inland Rail cut back to Melbourne–Parkes; Queensland and Brisbane legs shelved with no date", "category": "Decisions & judgement", "summary": "On 5–6 May 2026, ahead of the Budget, Catherine King announced the government would 'consolidate' the Melbourne–Brisbane Inland Rail freight line by completing only the Beveridge (Vic) to Parkes (NSW) sections by the end of 2027. She cited cost-assurance work putting the full project above $45 billion, 'more than three times the current budget allocation', with no completion possible before 2036; works north of Parkes, including Queensland's Gowrie–Kagaru section, are limited to corridor preservation. The project had been estimated at $16.4 billion in 2020 and about $31 billion in the 2023 Schott review, after which King had already deferred the northern sections. Queensland Deputy Premier Jarrod Bleijie called the decision 'a real kick in the guts', the Queensland Farmers' Federation 'an incredibly disheartening outcome for regional Australia', regional mayors in Toowoomba, Goondiwindi and Parkes expressed dismay, and the Coalition launched a 'Rescue our Rail' petition, arguing funds were redirected to Melbourne's Suburban Rail Loop. A Toowoomba business that had planned around the line for 25 years called it a 'disaster'.", "response": "King said the government was 'taking sensible decisions to realign the future of Inland Rail', blaming 'major deficiencies in the governance and delivery of Inland Rail by the Liberals and Nationals', and told the ABC the project had been 'underfunded and under-planned' and that continuing would 'actually hit the budget'.", "outcome": "Scaled back rather than formally cancelled: the Parkes–Brisbane legs, including all of Queensland, are shelved with no completion date. No formal finding; the Coalition's petition and Queensland Government objections are ongoing.", "status": "ongoing", "sources": [{"title": "Record investment in the freight rail network and consolidating Inland Rail (Minister King media release)", "url": "https://minister.infrastructure.gov.au/c-king/media-release/record-investment-freight-rail-network-and-consolidating-inland-rail", "date": "2026-05-06"}, {"title": "Albanese government axes funding for $45 billion Inland Rail project (ABC News)", "url": "https://www.abc.net.au/news/2026-05-05/albanese-government-slashes-funding-inland-rail-project/106644902", "date": "2026-05-05"}, {"title": "Cancellation 'disaster' for business that expected Inland Rail for 25 years (ABC News)", "url": "https://www.abc.net.au/news/2026-05-06/inland-rail-cancellation-reactions/106646490", "date": "2026-05-06"}, {"title": "Getting Inland Rail back on track: the 2023 Schott review response (Minister King media release)", "url": "https://minister.infrastructure.gov.au/c-king/media-release/getting-inland-rail-back-track", "date": "2023-04-06"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "oneil-1-2-million-homes-target", "date": "2026-04-22", "minister": "Clare O'Neil", "portfolio": "Minister for Housing and Homelessness", "title": "O'Neil defends 1.2 million homes target as construction falls 77,000 behind", "category": "Decisions & judgement", "summary": "The National Housing Accord target of 1.2 million new homes over five years to mid-2029 was running 77,000 homes (30 per cent) behind the required pace by April 2026, with the Housing Industry Association forecasting only 986,000 homes and just 890 of 40,000 promised social and affordable homes completed. O'Neil conceded the target may not be achievable but defended it as deliberately 'bold and ambitious'. By August 2026 the government's own expert panel pushed the expected date for reaching 1.2 million homes to the end of 2030 and Master Builders projected a shortfall of about 204,000 homes.", "response": "O'Neil said 'we want to be bold and ambitious about housing' and that the focus was to 'keep building, keep removing roadblocks'; the government has not conceded the target will be missed. Opposition spokesman Andrew Bragg said there was 'no chance' of meeting it.", "outcome": "No formal finding; target on track to be missed.", "status": "ongoing", "sources": [{"title": "Clare O'Neil defends 'unachievable' 1.2 million housing target", "url": "https://www.canberratimes.com.au/story/9230094/clare-oneil-defends-unachievable-12-million-housing-target/", "date": "2026-04-22"}, {"title": "Outlook worsens for government to meet 1.2 million houses promise", "url": "https://www.abc.net.au/news/2026-08-21/timeline-housing-accord-slips-further/107058404", "date": "2026-08-21"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "marles-wong-iran-strikes-legality", "date": "2026-03-02", "minister": "Richard Marles", "portfolio": "Minister for Defence; Minister for Foreign Affairs", "title": "Marles and Wong decline to say whether US-Israeli strikes on Iran were lawful", "category": "Conduct & remarks", "summary": "After the United States and Israel bombed Iran in early 2026, Marles and Wong repeatedly avoided questions on whether the strikes breached international law, with Marles saying 'the legality is a matter for both United States and Israel'. UN Special Rapporteur Ben Saul said international lawyers were 'united' that the strikes were unlawful and ANU's Don Rothwell noted pre-emptive self-defence has no accepted legal basis; Greens senator David Shoebridge asked why the Foreign Minister refused to discuss legality. On 20 March Australia was absent from a seven-nation allied statement on the Strait of Hormuz, prompting claims it was out of step.", "response": "Marles said Australia supported the US 'in preventing Iran acquiring this capability'; Wong said the Iranian people must determine their future. Albanese denied Australia was out of step with allies and said Australian personnel were in purely defensive roles.", "outcome": "No formal finding.", "status": "no-finding", "sources": [{"title": "Albanese government avoids questions on legality of US-Israeli strikes on Iran", "url": "https://www.abc.net.au/news/2026-03-02/albanese-government-questions-on-legality-of-us-strikes-on-iran/106403944", "date": "2026-03-02"}, {"title": "Iran war updates: Albanese denies Australia out of step with allies after release of joint statement", "url": "https://www.abc.net.au/news/2026-03-20/iran-israel-us-war-live-updates/106475836", "date": "2026-03-20"}, {"title": "During an illegal war in Iran, Albanese and Wong treat us like idiots", "url": "https://www.crikey.com.au/2026/03/05/illegal-us-war-iran-albanese-and-wong-treat-australians-like-idiots/", "date": "2026-03-05"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-grace-tame-difficult", "date": "2026-02-25", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM describes Grace Tame as 'difficult' in word-association game, issues qualified apology", "category": "Conduct & remarks", "summary": "At the Future Victoria conference in Melbourne on Wednesday 25 February 2026, Albanese took part in a rapid-fire one-word association segment and answered 'difficult' when given the name of Grace Tame, the 2021 Australian of the Year and child sexual abuse survivor advocate. Greens senators Larissa Waters and Sarah Hanson-Young criticised the label. Tame wrote on Instagram that the term is 'a misogynist's code for a woman who won't comply' and, after his apology, called it 'a patronising cop out from a total coward'.", "response": "Albanese said on 26 February: 'If there was any misinterpretation, then I certainly apologise. She has had a difficult life and that was what I was referring to.' He also criticised Tame's chanting of 'globalise the intifada' at a rally.", "outcome": "Qualified apology; no formal finding.", "status": "resolved", "sources": [{"title": "Former Australian of the Year Grace Tame responds to Anthony Albanese's 'difficult life' apology", "url": "https://www.abc.net.au/news/2026-02-26/albanese-apologises-for-calling-grace-tame-difficult/106389860", "date": "2026-02-26"}, {"title": "Albanese addresses 'difficult' Grace Tame comment as Tame compares him to Morrison", "url": "https://www.sbs.com.au/news/article/albanese-addresses-grace-tame-difficult-comment-after-calls-for-apology/6slxu9296", "date": "2026-02-26"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "chalmers-philip-lowe-persistent-critic", "date": "2026-02-18", "minister": "Jim Chalmers", "portfolio": "Treasurer", "title": "Chalmers suggests ex-RBA governor's spending critique stems from not being reappointed", "category": "Conduct & remarks", "summary": "After former Reserve Bank governor Philip Lowe wrote in the AFR that government 'handouts' would keep interest rates higher, Chalmers said it was 'a matter of public record Phil Lowe would have liked to have been reappointed by the government' and that 'after he wasn't reappointed he's become a fairly persistent critic of the Labor government'. The Prime Minister joined in with a jibe asking which 'Phil Lowe' was meant. Economists Saul Eslake and Richard Holden criticised the Treasurer's response, with Eslake saying it 'demeans the dignity of his office' and Holden warning it could curtail future governors' independence.", "response": "Chalmers rejected the claim that government spending was fuelling inflation and stood by his remarks.", "outcome": "No formal finding.", "status": "no-finding", "sources": [{"title": "Chalmers suggests ex-RBA governor's spending critique is due to personal vendetta", "url": "https://www.abc.net.au/news/2026-02-18/chalmers-dismisses-criticism-from-philip-lowe/106359398", "date": "2026-02-18"}, {"title": "Aaron Patrick: This is what happens when you cross Treasurer Jim Chalmers", "url": "https://thenightly.com.au/politics/aaron-patrick-this-is-what-happens-when-you-cross-treasurer-jim-chalmers-c-21687991", "date": "2026-02-19"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-herzog-invitation", "date": "2026-02-07", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM's invitation to Israeli President Herzog after Bondi attack draws calls to rescind", "category": "Decisions & judgement", "summary": "Albanese asked the Governor-General to invite Israeli President Isaac Herzog to visit Australia from 8 to 12 February 2026 as a show of support for the Jewish community after the Bondi terror attack. The Jewish Council of Australia released an open letter signed by more than 1,000 Jewish academics and community leaders urging the PM to rescind the invitation, saying it used 'Jewish grief as a political prop'; a UN Commission of Inquiry had earlier named Herzog among figures who 'incited the commission of genocide', and its Australian member Chris Sidoti said the invitation should be withdrawn. Large protests followed in Sydney and Melbourne.", "response": "Albanese urged people to 'recognise the solemn nature' of the visit; Penny Wong said Jewish leaders had urged the government to issue the invitation; Tony Burke and Michelle Rowland backed the visit as solidarity with Jewish Australians.", "outcome": "Visit proceeded; no formal finding.", "status": "no-finding", "sources": [{"title": "Albanese's invitation to Herzog is a shift in his approach to Israel", "url": "https://www.abc.net.au/news/2026-02-07/isaac-herzog-visit-australia/106294858", "date": "2026-02-07"}, {"title": "Who is Isaac Herzog, and why is his imminent Australian visit controversial?", "url": "https://www.sbs.com.au/news/article/isaac-herzog-australia-visit-controversy-explained/8rsgnrmic", "date": "2026-02-08"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "marles-defence-estate-sell-off-victoria-barracks", "date": "2026-02-05", "minister": "Richard Marles", "portfolio": "Minister for Defence", "title": "Marles' plan to sell historic barracks and other Defence sites draws heritage backlash", "category": "Decisions & judgement", "summary": "In February 2026 Marles announced Defence would divest dozens of 'underutilised' properties nationally, later reported as up to 86 sites worth an estimated $3 billion, including Sydney's 176-year-old Victoria Barracks, HMAS Penguin, Melbourne's Victoria Barracks and Hobart's Anglesea Barracks. Marles said the test was 'the best opportunity for a return to the Commonwealth'. Former PM Paul Keating accused Defence of trying to 'vandalise the national estate', RSL national president Peter Tinley warned of heritage loss and displacement of about 2,600 cadets, and community housing groups criticised the absence of an affordable-housing mandate. More than 100 submissions were made to a Senate inquiry.", "response": "Marles argued the public would gain better access to sites like HMAS Penguin; Assistant Defence Minister Peter Khalil said 'we are not going to bulldoze those heritage locations'.", "outcome": "Divestment continuing; Senate inquiry under way.", "status": "ongoing", "sources": [{"title": "Golf courses, barracks and museums: what Defence is selling off in Victoria", "url": "https://www.abc.net.au/news/2026-02-05/victoria-defence-assets-property-audit-divestment/106304518", "date": "2026-02-05"}, {"title": "Victoria Barracks, HMAS Penguin part of controversial plan to sell national defence assets", "url": "https://www.abc.net.au/news/2026-03-16/defence-sale-victoria-barracks-hmas-penguin-under-scrutiny/106460046", "date": "2026-03-16"}, {"title": "What will become of the Victoria Barracks? Communities have their say", "url": "https://www.abc.net.au/news/2026-05-07/victoria-barracks-defence-assets-sale-divest-community-responds/106625492", "date": "2026-05-07"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "rowland-hate-laws-israel-genocide-groups", "date": "2026-01-20", "minister": "Michelle Rowland", "portfolio": "Attorney-General", "title": "Rowland says groups accusing Israel of genocide could be banned if criteria met", "category": "Conduct & remarks", "summary": "As Parliament rushed through the Combatting Antisemitism, Hate and Extremism Bill 2026 after the Bondi attack, Rowland was asked on ABC 7.30 whether a group saying Israel was engaged in genocide, leaving Jewish Australians feeling harassed or intimidated, could be banned under the new hate-group listing regime. She replied: 'If those criteria are satisfied, then that is the case', while declining to rule specific conduct in or out. Constitutional lawyer Anne Twomey warned the laws gave ministers broad discretion and could chill legitimate political speech; the Greens said the laws risked silencing criticism of foreign governments, and a Senate amendment to protect criticism of Israel was defeated 43-12.", "response": "Rowland said the laws targeted groups such as the National Socialist Network and Hizb ut-Tahrir and were 'not designed to prevent differences of views', with further factors including ASIO advice needed before any listing.", "outcome": "Laws passed on 21 January 2026; no formal finding.", "status": "no-finding", "sources": [{"title": "Television interview – ABC 7:30 (transcript)", "url": "https://ministers.ag.gov.au/media-centre/transcripts/television-interview-abc-730-20-01-2026", "date": "2026-01-20"}, {"title": "New hate laws have passed parliament. What do they actually do?", "url": "https://www.abc.net.au/news/2026-01-21/what-will-new-hate-laws-do/106253754", "date": "2026-01-21"}, {"title": "Hate crime laws may have unintended consequences – including chilling free speech", "url": "https://theconversation.com/hate-crime-laws-may-have-unintended-consequences-including-chilling-free-speech-274016", "date": "2026-01-21"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-bondi-vigil-booed-apology", "date": "2025-12-21", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM booed at Bondi vigil, apologises to Jewish community over handling of antisemitism", "category": "Decisions & judgement", "summary": "One week after the 14 December 2025 Bondi Beach terror attack that killed 15 people at a Hanukkah event, Albanese was booed and heckled when introduced at the community vigil, while NSW Premier Chris Minns and Opposition Leader Kellie Sloane received standing ovations. NSW Jewish Board of Deputies president David Ossip asked how the attack could occur 'after two years of escalating antisemitism and warnings from the Jewish community and ASIO', and community leaders and the Opposition called for a royal commission. The next day Albanese said 'I'm sorry for what the Jewish community and our nation as a whole has experienced', acknowledged some of the anger 'was directed towards me', and announced tougher hate-speech laws and an inquiry led by former ASIO chief Dennis Richardson rather than a royal commission.", "response": "Albanese said the crowd was 'hurting and angry' and that he understood the anger directed at him; he defended a faster Richardson-led inquiry over a royal commission and announced new offences for hate preaching and radicalising children.", "outcome": "Apology issued; Richardson inquiry and hate-law package announced.", "status": "ongoing", "sources": [{"title": "Jewish community gathers for Bondi Beach shooting vigil and commemoration", "url": "https://www.abc.net.au/news/2025-12-21/nsw-bondi-massacre-vigil-commemoration-jewish-community/106168156", "date": "2025-12-21"}, {"title": "Anthony Albanese apologises for what Jewish community experienced after Bondi attack", "url": "https://www.abc.net.au/news/2025-12-22/government-proposes-offence-radicalising-children-bondi/106171326", "date": "2025-12-22"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "rowland-perth-family-trip-repayment", "date": "2025-12-14", "minister": "Michelle Rowland", "portfolio": "Attorney-General (Communications Minister at time of travel)", "title": "Rowland repays about $10,000 after IPEA finds Perth family trip partly outside guidelines", "category": "Taxpayer money & entitlements", "summary": "The Australian Financial Review reported in December 2025 that Rowland had billed taxpayers more than $21,000 for a week-long trip to Perth in July 2023, including $16,050 in family-reunion flights; the trip began with around 10 official engagements before a family holiday. Rowland referred the claims to the Independent Parliamentary Expenses Authority, which advised on 12 December 2025 that 'a portion of the family reunion travel expenses were outside the guidelines'.", "response": "Rowland's office said she 'formally accepted that advice' and 'commenced steps to make a repayment'. She later expressed regret, saying it 'shouldn't have happened'.", "outcome": "IPEA finding of partial non-compliance; Rowland repaid $7,932 in airfares plus a 25% penalty of $1,983 (about $10,000), confirmed 4 March 2026.", "status": "resolved", "sources": [{"title": "Attorney-General Michelle Rowland to repay family travel expenses after independent review", "url": "https://www.abc.net.au/news/2025-12-14/michelle-rowland-to-repay-expenses-claim/106140868", "date": "2025-12-14"}, {"title": "Attorney-general pays taxpayer back $8,000 for family flights", "url": "https://www.abc.net.au/news/2026-03-04/attorney-general-michelle-rowland-pays-taxpayer-back-for-flights/106416782", "date": "2026-03-04"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "farrell-family-travel-highest-spender", "date": "2025-12-10", "minister": "Don Farrell", "portfolio": "Minister for Trade and Tourism; Special Minister of State", "title": "Farrell named highest user of family travel entitlements at $48,178 in 2024–25", "category": "Taxpayer money & entitlements", "summary": "An ABC analysis of IPEA data (10 December 2025) found Farrell, the minister responsible for setting parliamentary expense rules, was the largest user of family-reunion travel in 2024–25 at $48,178 ($29,966 Canberra flights, $14,953 other domestic flights, $3,258 car costs); AAP reported his family travel exceeded $90,000 since 2022. Claims included family travel to Uluru, to Sydney coinciding with an opera performance, to Melbourne during a theatre premiere, and $5,760 for attending the 2023 and 2024 AFL grand finals with a family member. No breach of IPEA rules was alleged.", "response": "Farrell defended the travel as within the rules and tied to his tourism and trade duties, including presenting graduation certificates to Indigenous hospitality workers at Uluru.", "outcome": "No formal finding. The Remuneration Tribunal tightened family travel rules in January 2026 (economy-class only for spouses; non-Canberra family trips limited).", "status": "no-finding", "sources": [{"title": "Federal politicians charge taxpayers $1.1 million for family travel in 12 months", "url": "https://www.abc.net.au/news/2025-12-10/pollies-charge-taxpayers-for-family-travel/106122328", "date": "2025-12-10"}, {"title": "Travel expenses saga takes flight as PM defends rules (AAP)", "url": "https://aapnews.aap.com.au/news/travel-expenses-saga-takes-flight-as-pm-defends-rules", "date": "2025-12-11"}, {"title": "When can politicians put sport or family trips on the 'company card'?", "url": "https://www.abc.net.au/news/2025-12-13/when-can-sport-be-charged-to-taxpayers/106128390", "date": "2025-12-13"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "wells-sporting-events-family-travel-ipea-audit", "date": "2025-12-07", "minister": "Anika Wells", "portfolio": "Minister for Communications and Minister for Sport", "title": "Wells' taxpayer-funded travel to sporting events audited; four breaches, $10,116 repaid", "category": "Taxpayer money & entitlements", "summary": "In December 2025 the ABC, AFR and The Nightly reported Wells had charged taxpayers for family travel coinciding with sponsored tickets to AFL grand finals (2022–2025), Boxing Day Tests, the Australian Open and a Thredbo ski trip; Comcar waits of several hours at events; a $3,681 Adelaide trip that included a friend's birthday; three Paris trips totalling about $116,000 for the Rugby World Cup, Olympics and Paralympics; and, per The Nightly, at least $62,000 for 60-plus sporting events since 2022. On 9 December she self-referred 3.5 years of claims to IPEA. IPEA's 268-page audit of about 250 claims (8 May 2026) found four breaches: $1,208.98 for her husband's flights in February 2022, $5,513.37 for family flights and car hire three days before her ministerial swearing-in in May 2025, $726.29 for her husband's flight home the day after the 2025 AFL Grand Final, and $644.25 in car hire in regional NSW in October 2025. The Thredbo trip was found compliant.", "response": "In December Wells said: 'I absolutely accept those figures prompt a gut reaction in people' but that she had 'upheld' the rules. After the audit she said: 'I chose what I thought was the more sensible, cheaper option, but those choices were not allowed according to the rules, which I accept and respect ... I am sorry for making these honest mistakes.'", "outcome": "IPEA found four breaches; Wells repaid $10,116 ($8,093 plus a 25% penalty of $2,023). IPEA introduced new advance flagging of high-cost bookings. Wells remained in the ministry.", "status": "resolved", "sources": [{"title": "Coalition puts heat on Wells over trips to cricket and AFL with family", "url": "https://www.abc.net.au/news/2025-12-08/coalition-anika-wells-cricket-expenses-travel/106113546", "date": "2025-12-08"}, {"title": "Anika Wells refers herself for audit of travel expenses after outrage over taxpayer funded trips", "url": "https://thenightly.com.au/politics/anika-wells-refers-herself-for-audit-of-travel-expenses-after-outrage-over-taxpayer-funded-trips--c-20941636", "date": "2025-12-09"}, {"title": "Sports Minister Anika Wells repays $10,000 in travel costs after audit", "url": "https://www.abc.net.au/news/2026-05-08/anika-wells-repays-travel-costs-afl-grand-final/106658202", "date": "2026-05-08"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "wells-new-york-un-trip-flights", "date": "2025-12-07", "minister": "Anika Wells", "portfolio": "Minister for Communications and Minister for Sport", "title": "Wells' $94,828 business-class flights to New York for UN social-media-ban speech", "category": "Taxpayer money & entitlements", "summary": "Senate estimates figures reported in early December 2025 showed $94,828 was spent on business-class flights for Wells and two staff to attend the UN General Assembly in September 2025 to promote Australia's under-16 social media ban; the total trip cost was about $118,000. Wells delayed her departure two days after the Optus Triple Zero outage, and flights were rebooked at short notice on Air New Zealand. FOI documents released in February 2026 showed the rebooking added about $7,000 and that neither IPEA nor the travel agent flagged the fares. The Prime Minister confirmed his office approved the changed travel.", "response": "Wells said: 'I had to be in two places at once. It was a really tricky situation' and that 'people can have an opinion about whether it was worth the money'. Albanese said: 'We make decisions as a government. We spoke in the morning, and the minister travelled.'", "outcome": "IPEA's May 2026 audit found the New York trip compliant, noting Wells had 'very limited' alternative flight options; no repayment required for this trip.", "status": "no-finding", "sources": [{"title": "Prime minister's office approved Anika Wells's almost-$100,000 flights", "url": "https://www.abc.net.au/news/2025-12-07/pmo-approved-wells-flights/106111598", "date": "2025-12-07"}, {"title": "Anika Wells defends $100,000 taxpayer-funded trip", "url": "https://www.sbs.com.au/news/article/anika-wells-defends-taxpayer-funded-trip-costs/kc6e3jizp", "date": "2025-12-07"}, {"title": "FOI documents reveal how Anika Wells's New York trip costs escalated", "url": "https://www.abc.net.au/news/2026-02-04/foi-docs-show-details-of-anika-wells-new-york-trip/106305526", "date": "2026-02-04"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "chalmers-super-tax-unrealised-gains-retreat", "date": "2025-10-13", "minister": "Jim Chalmers", "portfolio": "Treasurer", "title": "Chalmers abandons tax on unrealised super gains after two-year fight", "category": "Decisions & judgement", "summary": "After defending for more than two years a plan to double the tax on superannuation earnings above $3 million, including taxing unrealised capital gains with an unindexed threshold, Chalmers announced on 13 October 2025 that the unrealised-gains element was dumped, the $3 million threshold would be indexed, a new $10 million tier at 40 per cent added, and the start date pushed to July 2026. Farmers, self-managed fund holders and former PM Paul Keating had campaigned against the original design. Shadow Treasurer Ted O'Brien said 'the treasurer has been chewed up and his tax plan has been chucked out'; the Greens said the policy had been 'further weakened'. The net budget cost of the changes was $4.2 billion over the forward estimates.", "response": "Chalmers called the revisions 'practical and pragmatic' and denied being 'rolled' by the Prime Minister ('Of course not').", "outcome": "Policy redesigned; no formal finding.", "status": "resolved", "sources": [{"title": "Jim Chalmers unveils major retreat on controversial superannuation changes", "url": "https://theconversation.com/jim-chalmers-unveils-major-retreat-on-controversial-superannuation-changes-267220", "date": "2025-10-13"}, {"title": "Was Chalmers taught a lesson in his fight over superannuation?", "url": "https://www.abc.net.au/news/2025-10-15/was-chalmers-taught-a-lesson-in-his-fight-over-superannuation/105891400", "date": "2025-10-15"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "wells-optus-triple-zero-outage-handling", "date": "2025-10-01", "minister": "Anika Wells", "portfolio": "Minister for Communications", "title": "Wells criticised over handling of fatal Optus triple-zero outage", "category": "Decisions & judgement", "summary": "On 18 September 2025 an Optus firewall upgrade caused around 600 triple-zero calls to fail for about 13 hours across SA, WA and the NT, with four deaths linked to the outage. Wells drew criticism for saying 'that's a question you should put to the Optus CEO' when asked whether Australians could be confident it would not recur, for describing herself as 'still a new minister to the industry', and for travelling to New York while the crisis unfolded. Senate estimates later heard Optus's first notification emails went to an outdated departmental address that was checked only every few days, and that Wells had characterised the early emails as indicating a 'minor outage'.", "response": "Wells said Optus had 'let Australians down' and that she had sought assurances and external oversight of its systems; the Prime Minister publicly backed her handling. Opposition Leader Sussan Ley said the minister was 'making excuses, saying she's only new'.", "outcome": "No formal finding against the minister; regulatory action against Optus and inquiries continued.", "status": "no-finding", "sources": [{"title": "Communications Minister Anika Wells finds herself in the eye of Optus political storm", "url": "https://www.abc.net.au/news/2025-10-01/anika-wells-optus-triple-0-calls-coalition/105836652", "date": "2025-10-01"}, {"title": "Optus wears blame but government needs to explain how it handled early advice", "url": "https://www.abc.net.au/news/2025-10-09/optus-triple-zero-communications-anika-wells-senate-estimates/105830532", "date": "2025-10-09"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "burke-nauru-408m-nzyq-deal", "date": "2025-08-30", "minister": "Tony Burke", "portfolio": "Minister for Home Affairs and Immigration", "title": "Burke signs $408m Nauru deal for NZYQ cohort on unannounced trip", "category": "Decisions & judgement", "summary": "On an unannounced visit to Nauru on 29 August 2025, Burke signed a memorandum of understanding under which Australia would pay $408 million up front plus about $70 million a year for Nauru to grant long-term visas to hundreds of non-citizens from the NZYQ cohort released from indefinite detention after the 2023 High Court ruling. The statement was not distributed through standard media channels. Greens senator David Shoebridge called it 'deeply immoral and unworkable', refugee groups described it as 'discriminatory, disgraceful and dangerous', and the Human Rights Law Centre said it offshored a problem the government had created. The Prime Minister later insisted the deal was 'hardly secret'.", "response": "Burke said 'anyone who doesn't have a valid visa should leave the country' and that the arrangement was a fundamental element of a functioning visa system.", "outcome": "Deal proceeded; no formal finding.", "status": "no-finding", "sources": [{"title": "Federal government inks $400m deal with Nauru to resettle people who have 'no legal right to stay in Australia'", "url": "https://www.abc.net.au/news/2025-08-30/federal-government-inks-400m-deal-for-nauru/105716134", "date": "2025-08-30"}, {"title": "Greens, refugee advocates criticise $400m deal with Nauru to deport former detainees", "url": "https://www.sbs.com.au/news/article/australia-nauru-deal-immigration-detainees-nzyq/wk6i07qln", "date": "2025-08-30"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-palestine-recognition-netanyahu-weak", "date": "2025-08-19", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "Netanyahu brands Albanese 'weak' after Palestine recognition and Rothman visa refusal", "category": "Decisions & judgement", "summary": "After Albanese announced on 11 August 2025 that Australia would recognise a Palestinian state at the UN in September and the government cancelled the visa of Israeli MP Simcha Rothman, Israel revoked visas for Australia's representatives to the Palestinian Authority and Prime Minister Netanyahu posted that 'history will remember Albanese for what he is: a weak politician who betrayed Israel and abandoned Australia's Jews'. Opposition Leader Sussan Ley said the episode was a 'direct consequence' of Albanese 'mismanaging international relationships'; the Executive Council of Australian Jewry urged de-escalation, warning about $2 billion in trade and security cooperation. Australia formally recognised Palestine on 21 September 2025, which the Coalition called 'a chilling act of concession to Hamas terrorists'.", "response": "Albanese said he would not take the comments personally and that 'I engage with people diplomatically'; Penny Wong called Israel's visa revocation 'unjustified' and said the Netanyahu government was 'isolating' Israel.", "outcome": "No formal finding; recognition proceeded.", "status": "no-finding", "sources": [{"title": "Netanyahu calls Albanese a 'weak politician' who has 'betrayed' Israel", "url": "https://www.abc.net.au/news/2025-08-19/netanyahu-says-anthony-albanese-has-betrayed-israel/105673924", "date": "2025-08-19"}, {"title": "'A weak politician': Benjamin Netanyahu says Anthony Albanese has 'betrayed' Israel", "url": "https://www.sbs.com.au/news/article/benjamin-netanyahu-says-anthony-albanese-has-betrayed-israel/8h1bt49v4", "date": "2025-08-19"}, {"title": "Australia formally recognises state of Palestine as Anthony Albanese arrives in US", "url": "https://www.abc.net.au/news/2025-09-21/australia-formally-recognises-state-of-palestine/105799238", "date": "2025-09-21"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "gallagher-pwc-contracts-ban-lifted", "date": "2025-08-07", "minister": "Katy Gallagher", "portfolio": "Minister for Finance", "title": "Gallagher distances herself as Finance clears PwC to bid for contracts again", "category": "Appointments & process", "summary": "In August 2025 the Department of Finance ended the arrangement under which PwC Australia had refrained from bidding for federal contracts since April 2024 following the tax-leaks scandal, concluding the firm now met ethical standards, while noting it already held three active government contracts worth $11.6 million. Greens senator Barbara Pocock called the decision 'gutless' and said the government had 'betrayed the Australian people'; Liberal senator Richard Colbeck and Labor senator Deborah O'Neill had also argued PwC should remain excluded, and parliamentary inquiry recommendations were yet to be enacted.", "response": "Gallagher said 'ministers are not involved in procurement decisions. It is a matter for the department' and described the pause as 'a voluntary agreement' by PwC; she and the department initially declined to comment.", "outcome": "PwC readmitted to bidding with monitoring until 2027; no formal finding.", "status": "no-finding", "sources": [{"title": "Govt labelled 'gutless' for lifting ban on PwC contracts", "url": "https://www.canberratimes.com.au/story/9035760/pwc-allowed-to-bid-for-government-contracts-again-finance-says/", "date": "2025-08-07"}, {"title": "Finance Minister Katy Gallagher addresses PwC contract controversy", "url": "https://www.canberratimes.com.au/story/9058256/finance-minister-katy-gallagher-addresses-pwc-contract-controversy/", "date": "2025-09-05"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "collins-live-sheep-package-under-the-radar", "date": "2025-07-15", "minister": "Julie Collins", "portfolio": "Minister for Agriculture, Fisheries and Forestry", "title": "Collins accused of 'flying under the radar' with WA live-sheep transition announcement", "category": "Conduct & remarks", "summary": "Collins travelled to Muchea saleyards in WA on 15 July 2025 to announce details of the $139.7 million package supporting the phase-out of live sheep exports by sea, including $40 million for processing capacity and $30 million for farmers. Key WA industry bodies said they were not invited or notified, and journalists reported receiving no media invitations. WAFarmers chief executive Trevor Whittington said 'there was no detail today – we got more out of that leaked document', and industry figures accused the minister of trying to avoid producers angry at the ban.", "response": "Collins denied dodging industry, saying 'the industry and the sector was also briefed about the details of the package prior to today's announcement' and pointing to 16 workshops with more than 300 participants.", "outcome": "No formal finding.", "status": "no-finding", "sources": [{"title": "Agriculture Minister Julie Collins denies 'flying under the radar' with live export transition announcement", "url": "https://www.abc.net.au/news/2025-07-15/live-sheep-export-ban-transition-julie-collins-announcement/105532880", "date": "2025-07-15"}, {"title": "Backlash over sheep export transition plan in WA", "url": "https://www.farmweekly.com.au/story/9017520/backlash-over-sheep-export-transition-plan-in-wa/", "date": "2025-07-17"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "clare-childcare-safety-should-have-been-fixed", "date": "2025-07-03", "minister": "Jason Clare", "portfolio": "Minister for Education", "title": "Clare concedes childcare safety reforms 'should have been fixed yesterday'", "category": "Decisions & judgement", "summary": "After Melbourne childcare worker Joshua Dale Brown was charged with more than 70 offences involving eight children, Clare faced questions about why a national Working with Children Check system recommended by the 2015 Royal Commission still did not exist and why centres had seven days to report incidents. On 7.30 he said 'why hasn't this been fixed yet? … The answer is it should have been fixed yesterday', and told reporters 'it's taken too long to do the work necessary'. Former royal commissioner Robert Fitzgerald called the delay 'shameful' and said the Commonwealth 'really didn't want to get involved' in coordinating a scheme.", "response": "Clare said reforms 'can't happen soon enough', asked his department to draft laws allowing funding to be cut from centres failing safety standards, and put WWCC harmonisation on the attorneys-general agenda.", "outcome": "Legislation and national reforms announced; no formal finding against the minister.", "status": "no-finding", "sources": [{"title": "Federal Education Minister Jason Clare says Working with Children Check reforms 'can't happen soon enough'", "url": "https://www.abc.net.au/news/2025-07-03/minister-criticises-working-with-children-reforms/105485620", "date": "2025-07-03"}, {"title": "Transcript – 7:30 with Sarah Ferguson", "url": "https://ministers.education.gov.au/clare/transcript-730-sarah-ferguson", "date": "2025-07-03"}, {"title": "Jason Clare responds to shocking childcare allegations", "url": "https://www.abc.net.au/news/2025-07-03/jason-clare-responds-to-shocking-childcare/105492742", "date": "2025-07-03"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "watt-north-west-shelf-approval", "date": "2025-05-28", "minister": "Murray Watt", "portfolio": "Minister for the Environment and Water", "title": "Watt approves Woodside's North West Shelf extension to 2070, facing court challenges", "category": "Decisions & judgement", "summary": "Two weeks into the portfolio, Watt proposed approval on 28 May 2025 of Woodside's North West Shelf gas plant operating until 2070, subject to conditions on Murujuga rock art, and gave final approval in September 2025. Environment groups said the facility would produce an estimated 4 billion tonnes of emissions over its life, and traditional owner Raelene Cooper pursued Federal Court action over heritage. In October 2025 the Australian Conservation Foundation and Friends of Australian Rock Art launched Federal Court challenges arguing Watt wrongly considered economic benefits of the unapproved Browse project and failed to assess climate impacts; FARA said he had 'sided with industry over ancient cultural heritage'.", "response": "Watt said his conditions 'were designed to prevent significant damage to the rock art which is the test required under the EPBC Act' and that the decision complied with the law; he declined further comment citing litigation.", "outcome": "Approval stands; Federal Court challenges ongoing.", "status": "ongoing", "sources": [{"title": "Murray Watt flags Woodside's North West Shelf project extension response could be delayed", "url": "https://www.abc.net.au/news/2025-06-12/woodside-north-west-shelf-gas-approval-response-delayed/105403522", "date": "2025-06-12"}, {"title": "Woodside North West Shelf gas project extension challenged in Federal Court", "url": "https://www.abc.net.au/news/2025-10-13/federal-court-appeals-over-woodside-north-west-shelf-extension/105884752", "date": "2025-10-13"}, {"title": "Murray Watt fails first test with Woodside North West Shelf approval", "url": "https://www.crikey.com.au/2025/05/29/murray-watt-woodside-north-west-shelf-approval-failure-environment/", "date": "2025-05-29"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "marles-factional-assassin-husic-dreyfus-dumped", "date": "2025-05-11", "minister": "Richard Marles", "portfolio": "Deputy Prime Minister and Minister for Defence", "title": "Husic calls Marles a 'factional assassin' after he and Dreyfus are dumped from cabinet", "category": "Appointments & process", "summary": "In the post-election factional carve-up, Industry Minister Ed Husic and Attorney-General Mark Dreyfus were removed from the frontbench while Victorian Right MPs Sam Rae, a Marles ally in his first term, and Daniel Mulino were promoted. On Insiders on 11 May 2025 Husic said 'people, when they look at a deputy prime minister, they expect to see a statesman, not a factional assassin', accused Marles of wielding 'a factional club to reshape the ministry', said the Prime Minister 'should have intervened' and suggested his advocacy on Gaza contributed to his removal. Dreyfus's removal left no Jewish MP on a federal frontbench for the first time in 15 years, drawing criticism from the Executive Council of Australian Jewry.", "response": "Albanese said 'what I have done is to allocate portfolios. That is the system that is there' and described his conversation with Husic as 'constructive'. Marles did not publicly respond to the 'assassin' remark in the cited reports.", "outcome": "New ministry sworn in 13 May 2025; no formal finding.", "status": "no-finding", "sources": [{"title": "Dumped cabinet minister says Richard Marles a 'factional assassin', and demotion partly due to outspoken views on Gaza", "url": "https://www.abc.net.au/news/2025-05-11/ed-husic-dumped-minister-gaza-partly-to-blame-speaking-out/105278932", "date": "2025-05-11"}, {"title": "Anthony Albanese unveils new-look frontbench after historic victory", "url": "https://www.abc.net.au/news/2025-05-12/labor-anthony-albanese-unveils-new-ministry/105280774", "date": "2025-05-12"}, {"title": "Dumped minister Ed Husic labels Deputy Prime Minister Richard Marles 'factional assassin'", "url": "https://theconversation.com/dumped-minister-ed-husic-labels-deputy-prime-minister-richard-marles-factional-assassin-255962", "date": "2025-05-11"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-plibersek-salmon-epbc-amendment", "date": "2025-03-25", "minister": "Anthony Albanese", "portfolio": "Prime Minister (bill bypassing Environment Minister Tanya Plibersek)", "title": "PM rushes EPBC amendment to shield Tasmanian salmon farming from Plibersek review", "category": "Decisions & judgement", "summary": "With Environment Minister Tanya Plibersek yet to decide reconsideration requests over 2012 approvals for salmon farming in Macquarie Harbour, home of the endangered Maugean skate, Albanese introduced in his own name a bill removing the minister's power to reconsider approvals more than five years old that rely on state regulation. It passed the House on 25 March 2025 with Coalition support, days before the election was called. Coalition spokesman Jonathon Duniam said it was 'passing strange' the bill was not in the Environment Minister's name, Greens senator Sarah Hanson-Young called the process 'rushed' and Greenpeace's Glenn Walker said the PM who 'promised to end extinctions' was 'doing the opposite'. Legal scholars noted a Senate committee had unanimously recommended against similar legislation four months earlier.", "response": "The government said the change protected jobs in Tasmania's north-west and pointed to funding for oxygenation trials and a captive-breeding program for the skate.", "outcome": "Legislation passed; the Commonwealth reaffirmed the Macquarie Harbour decision in August 2025 and legal challenges were flagged.", "status": "resolved", "sources": [{"title": "Changes to laws pass lower house in attempt to protect salmon jobs", "url": "https://www.abc.net.au/news/2025-03-25/pm-albanese-introduces-legislation-to-protect-salmon-farming/105088538", "date": "2025-03-25"}, {"title": "Protecting salmon farming at the expense of the environment – another step backwards for Australia's nature laws", "url": "https://theconversation.com/protecting-salmon-farming-at-the-expense-of-the-environment-another-step-backwards-for-australias-nature-laws-252814", "date": "2025-03-26"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-chinese-live-fire-notice-claim", "date": "2025-02-21", "minister": "Anthony Albanese", "portfolio": "Prime Minister (with Defence Minister Richard Marles)", "title": "PM's claim China gave notice of Tasman live-fire drill contradicted at Senate estimates", "category": "Misleading statements", "summary": "When Chinese warships conducted live-fire drills in the Tasman Sea on 21 February 2025, forcing 49 flight diversions, Albanese said the activity was 'consistent with international law' and indicated notice had been given. Senate estimates heard Airservices Australia learned of the danger at 9:58am only because a Virgin Australia pilot picked up the warship's broadcast on an emergency frequency, and Defence found out afterwards; Marles said Australia 'became aware of the issue during the course of the day'. Opposition leader Peter Dutton said the PM 'either wasn't briefed, that he's made up the facts, that he's got it wrong', and shadow defence minister Andrew Hastie called the response 'weak'.", "response": "Albanese said there was 'no risk of danger to any Australian assets'; Marles said China's failure to give the customary 12-24 hours' notice was 'disconcerting'; the government lodged a protest with Beijing and Penny Wong raised it with Wang Yi.", "outcome": "No formal finding.", "status": "no-finding", "sources": [{"title": "Chinese gave live fire warning with planes 'literally flying across the Tasman'", "url": "https://www.abc.net.au/news/2025-02-21/chinese-warship-pilot-hazard-east-coast/104966826", "date": "2025-02-21"}, {"title": "Virgin Airlines pilot first alerted authorities to Chinese live fire danger on Friday", "url": "https://www.abc.net.au/news/2025-02-25/virgin-airlines-alerted-chinese-live-fire/104977032", "date": "2025-02-25"}, {"title": "Grattan on Friday: Albanese falls victim to a Chinese burn", "url": "https://theconversation.com/grattan-on-friday-albanese-falls-victim-to-a-chinese-burn-251029", "date": "2025-02-27"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-qantas-upgrades-joyce-chairmans-lounge-book", "date": "2024-10-27", "minister": "Anthony Albanese", "portfolio": "Prime Minister (allegations relate to period as Transport Minister/shadow minister)", "title": "Book alleges PM sought Qantas upgrades from Alan Joyce; PM denies ever calling him", "category": "Integrity & conflicts of interest", "summary": "Joe Aston's book The Chairman's Lounge (October 2024) alleged Albanese received at least 22 free Qantas upgrades over more than a decade, liaised directly with then-CEO Alan Joyce about his personal travel, and in 2022 asked Joyce to give his son Nathan Chairman's Lounge membership. Opposition Leader Peter Dutton said Albanese should refer himself to the National Anti-Corruption Commission, and Nationals senator Bridget McKenzie sought disclosure of the number and value of upgrades. Independent senator David Pocock criticised the PM for taking several days to clarify.", "response": "Albanese said: 'From time to time, members of parliament receive upgrades. What's important is that they are declared. All of mine have been declared.' On 30 October his office said: 'The prime minister did not ever call Alan Joyce seeking an upgrade.' He described the claims as rumours 'to sell a book'.", "outcome": "No NACC referral or formal finding; upgrades were declared on the register of interests. Senate crossbench considered but did not establish a specific inquiry.", "status": "no-finding", "sources": [{"title": "Anthony Albanese defends free Qantas upgrades, stating all have been declared", "url": "https://www.abc.net.au/news/2024-10-27/anthony-albanese-defends-free-qantas-upgrades/104524476", "date": "2024-10-27"}, {"title": "Peter Dutton says Anthony Albanese should refer himself for corruption investigation over Qantas upgrades", "url": "https://www.abc.net.au/news/2024-10-29/anthony-albanese-evades-calls-qantas-boss-alan-joyce/104531074", "date": "2024-10-29"}, {"title": "Prime Minister Anthony Albanese denies ever calling Alan Joyce for Qantas upgrades", "url": "https://www.abc.net.au/news/2024-10-30/anthony-albanese-denies-calling-joyce-qantas-upgrades/104539966", "date": "2024-10-30"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-copacabana-house-purchase", "date": "2024-10-15", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM buys $4.3 million Copacabana clifftop home during housing affordability debate", "category": "Decisions & judgement", "summary": "On 15 October 2024 it was reported that Albanese was buying a four-bedroom clifftop house at Copacabana on the NSW Central Coast for $4.3 million, near his fiancée Jodie Haydon's family, partly funded by selling an inner-west investment property. Opposition Leader Peter Dutton said the purchase was 'a matter for the prime minister' but that he was worried about 'people who can't afford their mortgages'; Greens housing spokesman Max Chandler-Mather criticised 'property investor politicians'. A senior Labor source was quoted comparing it to Scott Morrison's Hawaii holiday.", "response": "Albanese said: 'When your relationship changes, your life changes' and 'As a prime minister, I earn a good income. I understand that I've been fortunate,' adding 'I know what it is like to struggle. My mum lived in the one public housing that she was born in for all of her 65 years.'", "outcome": "No formal finding; a matter of political judgement rather than rules.", "status": "no-finding", "sources": [{"title": "'I earn a good income': Albanese buys $4.3 million clifftop property to be close to future wife's family", "url": "https://www.abc.net.au/news/2024-10-15/anthony-albanese-buys-central-coast-property/104472726", "date": "2024-10-15"}, {"title": "'I know what it's like to struggle': Anthony Albanese defends $4.3m house purchase", "url": "https://www.sbs.com.au/news/article/i-know-what-its-like-to-struggle-anthony-albanese-defends-4-3m-house-purchase/o83d7rhfu", "date": "2024-10-15"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "marles-chief-of-staff-tarnawsky-bullying-complaint", "date": "2024-10-10", "minister": "Richard Marles", "portfolio": "Deputy Prime Minister and Minister for Defence", "title": "Marles' chief of staff says she was sidelined after raising bullying complaint", "category": "Integrity & conflicts of interest", "summary": "On 10 October 2024 Jo Tarnawsky, Marles' chief of staff, publicly alleged that after she raised concerns about bullying by a senior colleague during a flight home from Ukraine in April 2024, Marles told her the situation was not 'fixable', directed her to take leave and seek other employment, and she was subsequently locked out of the office for more than 200 days without an investigation. On 25 November 2024 she filed Federal Court proceedings for adverse action against the Commonwealth, Marles and the Prime Minister's chief of staff. She did not allege Marles himself bullied her.", "response": "Asked in Parliament whether he had complied with the Ministerial Code of Conduct, Marles said: 'The short answer to the question is I am satisfied.' His spokesperson said 'a number of her assertions and recollections are contested' and that she had 'been treated with respect and courtesy'.", "outcome": "Federal Court proceedings commenced November 2024; no adverse finding against Marles reported.", "status": "ongoing", "sources": [{"title": "Richard Marles 'satisfied' with his compliance of Ministerial Code of Conduct", "url": "https://www.capitalbrief.com/briefing/richard-marles-chief-of-staff-alleges-she-was-bullied-and-driven-out-of-job-b0e8e861-964c-48c0-9771-c5afefbd0998/", "date": "2024-10-10"}, {"title": "Chief of staff to Richard Marles launches legal action over claims she was forced out of job", "url": "https://www.abc.net.au/news/2024-11-25/chief-staff-tarnawsky-marles-legal-job-dismissal/104642438", "date": "2024-11-25"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "albanese-burke-gaza-visas-asio-vetting-claim", "date": "2024-09-03", "minister": "Anthony Albanese", "portfolio": "Prime Minister (with Home Affairs Minister Tony Burke)", "title": "PM's claim ASIO vetted every Gaza visa applicant contradicted by ASIO chief", "category": "Misleading statements", "summary": "Between October 2023 and August 2024 Australia granted 2,922 visas to Palestinians from Gaza and refused 7,111. Albanese said ASIO had individually vetted each applicant; ASIO Director-General Mike Burgess clarified that applicants are checked against a watchlist and ASIO assesses only cases referred by Home Affairs, and that his August Insiders comments on 'rhetorical support' for Hamas had been 'distorted'. Peter Dutton demanded the PM apologise to Burgess for misrepresenting ASIO's role, and more than 70 Coalition MPs wrote to Burke demanding no visas for Hamas supporters. In October Burke defended the security process after reports a visa holder had hosted Hamas figures at an art institute in 2019.", "response": "Albanese said 'I haven't undermined his authority. I've supported him' and accused Dutton of 'sowing division'; Burke said 'our security agencies work through the evidence that they have' and that no onshore visas had been cancelled.", "outcome": "No formal finding.", "status": "no-finding", "sources": [{"title": "ASIO boss Mike Burgess says his comments over Gaza visas were 'distorted', sparking political storm", "url": "https://www.abc.net.au/news/2024-09-03/mike-burgess-asio-boss-gaza-visas-comments-misrepresented/104301400", "date": "2024-09-03"}, {"title": "ASIO's Mike Burgess clarifies his comments on visas for Palestinians fleeing Gaza", "url": "https://www.sbs.com.au/news/article/asio-director-mike-burgess-says-his-views-on-visas-for-hamas-supporters-were-distorted/uw2imis3m", "date": "2024-09-03"}, {"title": "Tony Burke defends security officials amid allegations a Palestinian visa holder has links to Hamas", "url": "https://www.abc.net.au/news/2024-10-09/government-defends-asio-amid-coalition-palestinian-visa-concerns/104449122", "date": "2024-10-09"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "chalmers-rba-smashing-the-economy", "date": "2024-09-02", "minister": "Jim Chalmers", "portfolio": "Treasurer", "title": "Chalmers accused of 'warring with the RBA' over 'smashing the economy' remark", "category": "Conduct & remarks", "summary": "Ahead of weak national accounts, Chalmers said interest rate rises were 'smashing the economy', following earlier remarks that they were 'hammering' it. Shadow finance minister Jane Hume accused him of warring with the independent Reserve Bank and shifting blame, saying he had 'blamed overseas factors … then he blamed Philip Lowe, and now he's blaming his hand-picked replacement for Philip Lowe, Michele Bullock'. The Prime Minister acknowledged rate rises affected the economy but stopped short of endorsing the language; Governor Bullock declined to engage.", "response": "Chalmers said 'it's a fact' that higher rates were slowing the economy and that he was 'telling it like it is', later saying his comments should 'of course' not be read as an attack on the RBA.", "outcome": "No formal finding.", "status": "no-finding", "sources": [{"title": "Jim Chalmers blames interest rate rises for 'smashing' the economy, expects weak economic growth", "url": "https://www.abc.net.au/news/2024-09-02/jim-chalmers-blames-interest-rate-rises-smashing-economy/104298162", "date": "2024-09-02"}, {"title": "Treasurer Jim Chalmers says he's 'telling it like it is' on households, economy 'smashed' by RBA rate rises", "url": "https://thenightly.com.au/politics/australia/treasurer-jim-chalmers-says-hes-telling-it-like-it-is-on-households-economy-smashed-by-rba-rate-rises-c-15911586", "date": "2024-09-02"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "rowland-gambling-ad-ban-shelved", "date": "2024-08-13", "minister": "Michelle Rowland", "portfolio": "Minister for Communications", "title": "Rowland shelves promised response to Murphy inquiry's gambling-ad ban", "category": "Decisions & judgement", "summary": "The bipartisan June 2023 Murphy inquiry recommended a phased three-year ban on all gambling advertising. In August 2024 Rowland's office briefed stakeholders under non-disclosure agreements on a watered-down cap of two ads per hour per channel before 10pm and a ban around live sport, prompting criticism from crossbenchers, health researchers and Peta Murphy's widower Rod Glover. Rowland had said the government would respond by the end of 2024 but the legislation did not eventuate before the 2025 election, with the delay attributed to industry lobbying and 'the complexity of advertising reform'.", "response": "The Prime Minister cited 'unintended consequences' for regional broadcasters; Rowland said further consultation was needed.", "outcome": "No legislation introduced; reforms shelved.", "status": "ongoing", "sources": [{"title": "Online gambling reform had rare bipartisan support thanks to a brave MP. So why has Labor put action on hold?", "url": "https://www.abc.net.au/news/2024-08-13/peta-murphy-left-online-gambling-legacy-why-isn-t-labor-adopting/104217328", "date": "2024-08-13"}, {"title": "Will the government's online gambling advertising legislation ever eventuate? Don't bet on it", "url": "https://theconversation.com/will-the-governments-online-gambling-advertising-legislation-ever-eventuate-dont-bet-on-it-238084", "date": "2025-02-20"}], "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "shorten-speechwriter-620k-contract", "date": "2024-06-03", "minister": "Bill Shorten", "portfolio": "Minister for the NDIS and Minister for Government Services", "title": "Services Australia's $620,000 two-year speechwriter contract for Shorten questioned", "category": "Taxpayer money & entitlements", "summary": "Senate estimates in June 2024 revealed Services Australia had awarded a contract worth about $620,499 over two years (around $300,000 a year) to speechwriter Julianne Stewart to write for the agency and for Shorten, with $447,516 paid after 20 months. The agency said it faced 'market failure' when recruiting in July 2022 and could not say who proposed the contract. Coalition figures Paul Fletcher and James Stevens called it 'bizarre' and 'ridiculous', contrasting it with Shorten's push to reduce NDIS spending.", "response": "Shorten said he had 'no idea what the payment was', that 'I'm not responsible for negotiating a contract' and that the speechwriter 'does a very good job' including training and mentoring staff.", "outcome": "No formal finding; the contract was a departmental procurement.", "status": "no-finding", "sources": [{"title": "Taxpayers set to fork out up to $600,000 for Bill Shorten's speechwriter over two years", "url": "https://www.abc.net.au/news/2024-06-03/speechwriter-paid-300k-annually-to-assist-bill-shorten/103928556", "date": "2024-06-03"}, {"title": "Bill Shorten denies link to $620k speechwriter contract", "url": "https://www.canberratimes.com.au/story/8651650/bill-shorten-denies-link-to-620k-speechwriter-contract/", "date": "2024-06-04"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "giles-direction-99-visa-reinstatements", "date": "2024-05-29", "minister": "Andrew Giles", "portfolio": "Minister for Immigration, Citizenship and Multicultural Affairs", "title": "Giles' Direction 99 blamed for tribunal reinstating visas of serious offenders", "category": "Decisions & judgement", "summary": "Ministerial Direction 99, issued by Giles in early 2023 after commitments to New Zealand, required decision-makers to weigh a non-citizen's ties to Australia when considering visa cancellations. In May 2024 it emerged the Administrative Appeals Tribunal had cited the direction when reinstating visas of people convicted of serious offences, including a man later charged with murder in Brisbane. The Coalition called for Giles' resignation over several weeks of Question Time.", "response": "Giles acknowledged the direction 'has not produced, in the AAT decisions, the outcomes that we expected' but refused to resign; the government re-cancelled a number of visas and announced a replacement direction.", "outcome": "Direction 99 replaced by Direction 110 on 7 June 2024, prioritising community safety. Giles was moved from the immigration portfolio in the July 2024 reshuffle.", "status": "resolved", "sources": [{"title": "Immigration Minister Andrew Giles won't step aside despite tearing up contentious direction to department", "url": "https://www.abc.net.au/news/2024-05-29/andrew-giles-wont-resign/103909444", "date": "2024-05-29"}, {"title": "Andrew Giles issues replacement to 'direction 99' which he says prioritises community safety", "url": "https://www.abc.net.au/news/2024-06-07/giles-issues-new-ministerial-direction/103949446", "date": "2024-06-07"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "pm-no-more-rally-canberra-2024", "date": "2024-04-28", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM's on-stage exchange with organiser of Canberra rally against gendered violence", "category": "Conduct & remarks", "summary": "At the 'No More' national rally against gendered violence outside Parliament House on 28 April 2024, organiser Sarah Williams (What Were You Wearing) told the crowd 'We gave the opportunity to Anthony Albanese to make comments today and we didn't get any'. Albanese, seated nearby, was recorded by Nine saying 'No, you haven't!' and on ABC footage 'Do you want me to speak or not? I'm the prime minister.' Taking the microphone, he said he and Katy Gallagher had asked to speak and 'were told that wasn't possible and that's fine, I respect the organisers' right to do that'. Williams replied 'That's a lie, that's a full-out lie' and broke down in tears; she later said his office had told her he only wanted to walk 'in solidarity', that 'he never asked to speak', and that he had muttered 'I'm the Prime Minister, I run this country', a line the SMH could not verify and which is not on the footage.", "response": "Albanese said it was 'an emotional day', that 'I was happy not to speak, I was happy to speak', and declined to confirm or deny the 'I run this country' line ('I'm not going to get into that sort of debate'). Gallagher said talks to get on the speakers' list 'weren't able to land' because of disagreement over the rally's five demands. Peter Dutton said the PM 'needs to apologise if he has lied'; David Littleproud called him 'tone deaf'.", "outcome": "No apology or correction. On 30 April Albanese declined to apologise ('I wish her well. People can see the video for themselves'); Williams said no one from his office had contacted her. No formal finding.", "status": "no-finding", "sources": [{"title": "Albanese reminded how rallies have the ability to haunt the nation's leaders (ABC)", "url": "https://www.abc.net.au/news/2024-04-29/albanese-rally-gender-based-violence-parliament-house/103780082", "date": "2024-04-29"}, {"title": "PM brushes off accusation he lied about speaking arrangements at rally (Guardian Australia)", "url": "https://www.theguardian.com/australia-news/2024/apr/29/no-more-violence-against-women-rally-canberra-anthony-albanese-speaking-arrangements", "date": "2024-04-29"}, {"title": "'I wish her well': Albanese declines to apologise to Sarah Williams (SMH)", "url": "https://www.smh.com.au/politics/federal/i-wish-her-well-albanese-declines-to-apologise-to-sarah-williams-20240430-p5fnr0.html", "date": "2024-04-30"}, {"title": "Albanese plays down claims from rally organiser he lied about invitation to speak (ABC)", "url": "https://www.abc.net.au/news/2024-04-29/albanese-plays-down-claim-lied-women-rally-invitation-to-speak/103778800", "date": "2024-04-29"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-stage-3-tax-cuts-broken-promise", "date": "2024-01-25", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "Albanese breaks 'my word is my bond' pledge on stage 3 tax cuts", "category": "Misleading statements", "summary": "Having repeatedly promised before and after the 2022 election to keep the legislated stage 3 tax cuts unchanged, declaring 'my word is my bond', Albanese announced in January 2024 that the cuts would be restructured to give larger relief to earners under $200,000 and less to high earners, redirecting about $28 billion over a decade. On Insiders on 4 February he faced questions about his integrity and said 'I'm an honest person. I am up-front', attributing the change to shifting economic circumstances. The Coalition labelled it a broken promise but voted for the revised package, which passed Parliament in February 2024.", "response": "Albanese said he had 'listened to people' struggling with cost of living and that circumstances had changed since the promise was made.", "outcome": "Revised tax cuts legislated; no formal finding.", "status": "resolved", "sources": [{"title": "Anthony Albanese rebuffs questions of integrity as he defends stage 3 tax cut changes", "url": "https://www.abc.net.au/news/2024-02-04/anthony-albanese-insiders-stage-3-tax-cuts/103424808", "date": "2024-02-04"}, {"title": "Stage 3 tax backflip saw Anthony Albanese's entry into the annals of one liners that were a good idea at the time", "url": "https://www.abc.net.au/news/2024-02-08/stage-3-tax-cuts-my-word-is-my-bond/103443980", "date": "2024-02-08"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "oneil-giles-nzyq-detainee-releases", "date": "2023-11-08", "minister": "Clare O'Neil", "portfolio": "Minister for Home Affairs (with Immigration Minister Andrew Giles)", "title": "NZYQ detainee releases: O'Neil corrects 'legal advice' remark amid 'botched' claims", "category": "Decisions & judgement", "summary": "After the High Court's 8 November 2023 NZYQ ruling that indefinite immigration detention was unlawful, more than 90 (later about 140) people, some with serious convictions, were released. The government rushed through curfew and ankle-monitor laws and later a preventative detention regime. On 22 November O'Neil said she had considered releasing the NZYQ plaintiff to avoid a broader ruling ('It was considered and we decided not to do it') and clarified that earlier remarks about acting on 'legal advice' had been misleading, as she had been referring to 'operational and policy conversations'. Shadow attorney-general Michaelia Cash said the government had 'botched' its response.", "response": "O'Neil and Giles said the government was 'moving quickly to finalise a tough preventative detention regime' and announced a $255 million response package.", "outcome": "Legislation passed in November–December 2023; no formal finding against either minister. Both were moved from the portfolios in July 2024.", "status": "no-finding", "sources": [{"title": "Clare O'Neil says she considered releasing child sex offender to avoid High Court immigration ruling", "url": "https://www.abc.net.au/news/2023-11-22/minister-considered-releasing-rapist-head-off-high-court-ruling/103134572", "date": "2023-11-22"}, {"title": "Government to introduce 'tough' preventative detention for detainees released by High Court order", "url": "https://www.abc.net.au/news/2023-11-28/high-court-full-reasons-indefinite-immigration-detention/103158998", "date": "2023-11-28"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "husic-gaza-collective-punishment-remarks", "date": "2023-10-19", "minister": "Ed Husic", "portfolio": "Minister for Industry and Science", "title": "Husic says Palestinians are being 'collectively punished', prompting Opposition criticism", "category": "Conduct & remarks", "summary": "On 19 October 2023 Husic said he felt 'very strongly that Palestinians are being collectively punished here for Hamas' barbarism' and that Australia should 'speak up for Palestinians', while condemning Hamas and supporting Israel's right to defend itself. Opposition deputy leader Sussan Ley accused him of 'freelancing on foreign policy' and Peter Dutton said the comments showed 'deep division' in Labor; the Executive Council of Australian Jewry described his statements as 'very troublesome for the community'.", "response": "Husic stood by the remarks. Foreign Minister Penny Wong said 'every innocent life matters'; Home Affairs Minister Clare O'Neil declined to endorse the 'collective punishment' characterisation.", "outcome": "No formal finding. Husic was dropped from cabinet after the May 2025 election in a factional decision he later said was partly linked to his views on Gaza.", "status": "no-finding", "sources": [{"title": "'Speak up for Palestinians': Frontbencher Ed Husic says Palestinians are being collectively punished in Gaza", "url": "https://www.abc.net.au/news/2023-10-19/husic-says-palestinians-being-collectively-punished/102995306", "date": "2023-10-19"}, {"title": "Cabinet Minister Ed Husic says Palestinians are being 'collectively punished' for Hamas' barbarism", "url": "https://theconversation.com/cabinet-minister-ed-husic-says-palestinians-are-being-collectively-punished-for-hamas-barbarism-216008", "date": "2023-10-19"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "king-qatar-airways-decision-senate-inquiry", "date": "2023-10-03", "minister": "Catherine King", "portfolio": "Minister for Infrastructure, Transport, Regional Development and Local Government", "title": "King's rejection of extra Qatar Airways flights scrutinised amid Qantas lobbying claims", "category": "Decisions & judgement", "summary": "In July 2023 King rejected Qatar Airways' request for 28 additional weekly flights to Sydney, Melbourne and Brisbane, citing the national interest. Amid high airfares and evidence that Qantas had lobbied against the bid, a Senate select committee examined the decision; Virgin Australia's CEO testified King had relayed that Alan Joyce was 'not happy'. King declined to appear, saying it is 'long-standing practice that House of Representatives members do not appear before Senate committees'. The committee's 9 October 2023 report found 'the national interest would have been well served by agreeing to Qatar's request' and recommended an immediate review.", "response": "King called the inquiry 'a political stunt from the Coalition' and a 'ridiculous farce', saying she was 'doing the hard work'; Labor senators issued a dissenting report citing 'inaccuracies and obvious bias'.", "outcome": "Senate committee recommendations; government did not reverse the decision. No formal finding of misconduct.", "status": "no-finding", "sources": [{"title": "'Time wasting': Transport minister rebuffs request to front airlines inquiry", "url": "https://www.abc.net.au/news/2023-10-03/transport-minister-rebuffs-request-to-front-airlines-inquiry/102930208", "date": "2023-10-03"}, {"title": "Senate inquiry calls for 'immediate action' to review federal government's Qatar Airways flight decision as final report released", "url": "https://www.abc.net.au/news/2023-10-09/qatar-qantas-inquiry-committee-report/102953820", "date": "2023-10-09"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "albanese-son-qantas-chairmans-lounge", "date": "2023-09-10", "minister": "Anthony Albanese", "portfolio": "Prime Minister", "title": "PM's adult son granted Qantas Chairman's Lounge membership", "category": "Integrity & conflicts of interest", "summary": "In August–September 2023 it was reported that Qantas had granted Chairman's Lounge membership to the Prime Minister's adult son, Nathan, a decision requiring sign-off by senior Qantas leadership; parliamentarians and their spouses are routinely invited but other family members are not. The revelation came during a Senate inquiry into Qantas, at which five of seven committee senators had declared their own membership. Joe Aston's October 2024 book later alleged Albanese had asked Alan Joyce for the membership in 2022.", "response": "Albanese did not deny the 2024 claim that he asked for the membership; his spokesperson dismissed Opposition calls for a referral as 'a pathetic attempt at creating a headline'.", "outcome": "No formal finding; membership was disclosed.", "status": "no-finding", "sources": [{"title": "Inside the secretive and controversial Qantas Chairman's Lounge", "url": "https://www.abc.net.au/news/2023-09-10/inside-the-secretive-qantas-chairmans-lounge/102820726", "date": "2023-09-10"}, {"title": "Senate crossbench mulls inquiry into Albanese's Qantas upgrades", "url": "https://www.capitalbrief.com/article/senate-crossbench-mulls-inquiry-into-albaneses-qantas-upgrades-ab52c9ab-1726-4993-b0f2-bfa85ece9748/preview/", "date": "2024-10-29"}, {"title": "Anthony Albanese defends free Qantas upgrades, stating all have been declared", "url": "https://www.abc.net.au/news/2024-10-27/anthony-albanese-defends-free-qantas-upgrades/104524476", "date": "2024-10-27"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "marles-raaf-vip-flights", "date": "2023-09-01", "minister": "Richard Marles", "portfolio": "Deputy Prime Minister and Minister for Defence", "title": "Marles' $3.6m in RAAF VIP flights, including trips to Avalon near his Geelong home", "category": "Taxpayer money & entitlements", "summary": "Documents obtained by Greens senator David Shoebridge showed Marles' office had spent more than $3 million on RAAF special purpose flights since April 2022, second only to the Prime Minister. Capital Brief later reported via FOI that 155 flights cost $3.6 million between April 2022 and June 2023, with flight-tracker data showing more than 70 movements to or from Avalon Airport near Geelong; Defence declined to release routes citing an AFP security review. Shadow defence minister Andrew Hastie also questioned whether Marles carried golf clubs on VIP flights after photos of him golfing in Cambodia.", "response": "Marles said 'a lot of people travel on those flights, my direct component is a fraction of the number that has been reported' and 'everywhere I have gone, everything I have done has been on behalf of the Australian people', noting comparable spending by predecessors Peter Dutton and Barnaby Joyce.", "outcome": "No formal finding; flights were within entitlements.", "status": "no-finding", "sources": [{"title": "Defence Minister Richard Marles defends $3 million spend on taxpayer-funded RAAF flights", "url": "https://www.abc.net.au/news/2023-09-01/marles-defends-raaf-flights-taxpayer-spend/102316042", "date": "2023-09-01"}, {"title": "Opposition targets Defence Minister Richard Marles over RAAF flights and golf clubs", "url": "https://www.abc.net.au/news/2023-09-04/richard-marles-vip-jet-golf-questions-defence-minister-/102812384", "date": "2023-09-04"}, {"title": "Defence Minister Richard Marles spent $3.6m on 155 VIP flights", "url": "https://www.capitalbrief.com/article/defence-minister-richard-marles-vip-flights-binge-14851a1d-2745-43ff-9adb-ec222816ec2b/", "date": "2023-12-18"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "gallagher-higgins-knowledge-senate-statement", "date": "2023-06-13", "minister": "Katy Gallagher", "portfolio": "Minister for Finance, Minister for Women, Minister for the Public Service", "title": "Gallagher accused of misleading Senate over prior knowledge of Higgins allegation", "category": "Misleading statements", "summary": "Private messages between Brittany Higgins and her partner David Sharaz, leaked to The Australian in June 2023, indicated the pair contacted Gallagher days before Higgins' allegation became public in February 2021. At Senate estimates on 4 June 2021 Gallagher had told Senator Linda Reynolds 'no one had any knowledge. How dare you?'. The Coalition accused her of misleading Parliament and of collusion.", "response": "In a Senate statement on 13 June 2023 Gallagher said she had received a 'heads up' but 'I did nothing with that information. Absolutely nothing,' and 'I did not mislead the Senate at Senate estimates on June the 4th, 2021.'", "outcome": "No referral to the Privileges Committee proceeded; no formal finding.", "status": "no-finding", "sources": [{"title": "Katy Gallagher offers full denial to Senate over Brittany Higgins allegations", "url": "https://www.abc.net.au/news/2023-06-13/katy-gallagher-fronts-senate-brittany-higgins-knowledge/102469532", "date": "2023-06-13"}, {"title": "'I did not mislead the Senate', says Katy Gallagher", "url": "https://www.newcastleherald.com.au/story/8232623/i-did-nothing-gallagher-praises-higgins-denies-misleading-parliament/", "date": "2023-06-13"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "rowland-sportsbet-donations", "date": "2023-02-09", "minister": "Michelle Rowland", "portfolio": "Minister for Communications", "title": "Rowland accepted Sportsbet dinner and $10,000 donation before 2022 election", "category": "Integrity & conflicts of interest", "summary": "Nine newspapers reported on 9 February 2023 that Sportsbet paid about $8,960 for a dinner supporting Rowland's campaign in March 2022 and donated $10,000 in the days before the May 2022 election, both below the $15,000 disclosure threshold. As Communications Minister Rowland is responsible for online gambling regulation. Independent MP Andrew Wilkie said her position was 'patently untenable' and Greens senator Larissa Waters said it was 'clearly untenable for the minister to remain as gambling regulator'.", "response": "Rowland's spokesperson said all donations were 'compliant with the disclosure requirements of the AEC' and that she was not in breach of the ministerial code. On 20 February 2023 Rowland said: 'I will not take money from Sportsbet' in future.", "outcome": "No formal finding; Rowland retained the portfolio and later became Attorney-General.", "status": "no-finding", "sources": [{"title": "Communications Minister Michelle Rowland urged to quit over reportedly accepting Sportsbet donations", "url": "https://www.abc.net.au/news/2023-02-09/michelle-rowland-called-to-quit-over-sportsbet-donations/101951890", "date": "2023-02-09"}, {"title": "Anthony Albanese under pressure to sack minister over gambling donations", "url": "https://www.sbs.com.au/news/article/anthony-albanese-under-pressure-to-sack-minister-over-gambling-donations/vx3x0l8io", "date": "2023-02-09"}, {"title": "Michelle Rowland says she won't accept donations from betting companies again", "url": "https://www.abc.net.au/news/2023-02-20/rowland-won-t-accept-donations-from-gambling-companies-in-future/102001272", "date": "2023-02-20"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "dreyfus-higgins-settlement-nacc", "date": "2022-12-13", "minister": "Mark Dreyfus", "portfolio": "Attorney-General", "title": "Dreyfus' approval of $2.4m Higgins settlement referred to NACC; no corruption issue found", "category": "Decisions & judgement", "summary": "In December 2022 the Commonwealth settled Brittany Higgins' compensation claim for $2.4 million after a one-day mediation from which former minister Linda Reynolds was excluded. Peter Dutton and others questioned the speed and size of the payout, and Reynolds referred Dreyfus' handling of the process to the National Anti-Corruption Commission. Reynolds' Federal Court claim against the Commonwealth in 2025 alleged Dreyfus had a conflict of interest and committed misfeasance; those allegations were removed from the claim in November 2025.", "response": "The NACC said 'The then-attorney-general approved the settlement in accordance with the departmental advice' and there was no inappropriate ministerial intervention. Dreyfus (by then out of the ministry) criticised the NACC over the time taken.", "outcome": "NACC found on 12 June 2025 that 'no corruption issue arises'. Allegations against Dreyfus were dropped from Reynolds' lawsuit in November 2025.", "status": "resolved", "sources": [{"title": "Corruption watchdog clears Brittany Higgins' $2.4m payout", "url": "https://www.canberratimes.com.au/story/8990461/corruption-watchdog-clears-brittany-higgins-24m-payout/", "date": "2025-06-12"}, {"title": "Allegations against ex-Attorney-General Mark Dreyfus removed from Linda Reynolds action against Commonwealth", "url": "https://www.abc.net.au/news/2025-11-12/-mark-dreyfus-allegations-removed-from-linda-reynolds-lawsuit/106001236", "date": "2025-11-12"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "plibersek-dutton-voldemort-remark", "date": "2022-05-26", "minister": "Tanya Plibersek", "portfolio": "Incoming Minister for the Environment and Water (Labor frontbencher; sworn in 1 June 2022)", "title": "Plibersek apologises for saying Peter Dutton 'looks a bit like Voldemort'", "category": "Conduct & remarks", "summary": "Days after the May 2022 election, Plibersek told Nine Radio (4BC) that with Dutton set to become Opposition Leader, 'there will be a lot of children who have watched a lot of Harry Potter films who will be very frightened of what they are seeing on TV at night' and 'he looks a bit like Voldemort'. She was a Labor frontbencher at the time and was sworn in as a minister on 1 June 2022.", "response": "Plibersek phoned Dutton to apologise and told 2GB 'I shouldn't have said it'. Albanese said the comment was unacceptable and that she did the right thing by apologising, saying he wanted to 'change the way that politics functions in this country'.", "outcome": "Private and public apology; Dutton said it was 'water off a duck's back'.", "status": "resolved", "sources": [{"title": "Peter Dutton seeks to recast his image as Tanya Plibersek apologises for likening him to Voldemort", "url": "https://www.abc.net.au/news/2022-05-26/peter-dutton-recast-image-tanya-plibersek-voldemort-comment/101100708", "date": "2022-05-26"}, {"title": "Tanya Plibersek apologises for comparing Peter Dutton to Voldemort (2GB)", "url": "https://www.2gb.com/tanya-plibersek-apologises-for-comparing-peter-dutton-to-voldemort/", "date": "2022-05-26"}], "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}], "generated_at": "2026-09-18T07:36:31+00:00"};
